/* EmojiDrops — defensive runtime health layer */
(() => {
  'use strict';
  const $=s=>document.querySelector(s);
  const money=v=>Math.round(Number(String(v??0).replace(/[^0-9.,-]/g,'').replace(',','.'))||0);
  function profileActions(){const actions={profileSettingsBtn:()=>window.openSettings?.(),profileBackBtn:()=>window.closeProfile?.(),profileUpgradeBtn:()=>window.openUpgradeMenu?.(),profileStatsBtn:()=>window.openStats?.(),profileHistoryBtn:()=>window.openHistory?.(),profileLogoutBtn:()=>window.logout?.(),settingsCloseBtn:()=>window.closeSettings?.(),statsCloseBtn:()=>window.closeStats?.(),historyCloseBtn:()=>window.closeHistory?.()};Object.entries(actions).forEach(([id,fn])=>{const el=document.getElementById(id);if(!el||el.dataset.healthBound)return;el.dataset.healthBound='1';el.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();try{fn()}catch(err){console.error('[EmojiDrops]',id,err)}})})}
  function profile(){const b=$('#profileBalance');if(b)b.textContent=String(money(window.state?.balance))}
  function caseItems(){const box=$('#caseItemsList'),pool=window.state?.currentCase;if(!box||!Array.isArray(pool)||!pool.length||box.children.length===pool.length)return;box.innerHTML='';pool.forEach(item=>{const d=document.createElement('article');d.className='case-item-card';d.innerHTML=`<div class="case-item-emoji">${item.emoji||'❔'}</div><div class="case-item-name">${item.name||'Предмет'}</div><div class="case-item-price">${item.price||'0₽'}</div>`;box.appendChild(d)})}
  function multi(){const box=$('#multiRouletteContainer');if(!box)return;const n=Math.max(1,Math.min(10,Number(window.state?.openAmount)||1)),pool=window.state?.currentCase||[];if(!pool.length||(box.dataset.amount===String(n)&&box.children.length===n))return;box.dataset.amount=String(n);box.innerHTML='';for(let i=0;i<n;i++){const lane=document.createElement('div');lane.className='multi-roulette';lane.innerHTML='<div class="new-pointer"></div><div class="multi-track"></div>';const track=lane.lastElementChild;for(let j=0;j<36;j++){const item=window.getRandomByChance?.(pool)||pool[j%pool.length],x=document.createElement('div');x.className='item';x.textContent=item.emoji||'❔';track.appendChild(x)}box.appendChild(lane)}}
  const run=()=>{profileActions();profile();caseItems();multi()};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(run,150),{once:true});else setTimeout(run,150);setInterval(run,800);
})();